/* Motivo obrigatório: desfazer, estornar, aceitar perda, cancelar. O texto vai para a trilha. */
let F2_MOTCB=null;
function f2Motivo(titulo,texto,cb,rotulo,cls){F2_MOTCB=cb;openModal(`${mh(titulo)}<div class="mb"><p style="font-size:14px">${texto}</p><div class="field"><label for="f2Mot">Motivo <span class="req">*</span></label><textarea class="in" id="f2Mot" rows="3" placeholder="Escreva o motivo (pelo menos 10 letras). Fica na trilha com o seu nome e a hora."></textarea><div class="msg" id="f2MotMsg"></div></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn ${cls||''}" onclick="f2MotOk()">${rotulo||'Confirmar'}</button></div>`)}
function f2MotOk(){const el=$('#f2Mot');const m=(el&&el.value||'').trim();if(m.length<10){el.closest('.field').classList.add('err');$('#f2MotMsg').textContent='O motivo é obrigatório, com pelo menos 10 letras.';el.focus();return}closeModal();const cb=F2_MOTCB;F2_MOTCB=null;if(cb)cb(m)}
