/* Candidatos: só da mesma unidade (isolamento) e do mesmo sentido (entrada = receber, saída = pagar). O servidor calcula; aqui é a mesma regra. */
function cbScore(e,t){if(e.tit===t.id)return e.conf||100;let s=0;const v=Math.abs(e.v);if(Math.abs(v-t.v)<0.005)s+=55;else if(Math.abs(v-t.v)/t.v<=0.02)s+=30;const pal=semAc(e.desc).split(/[^a-z]+/).filter(p=>p.length>3);if(pal.some(p=>semAc(t.q).includes(p)))s+=25;if(e.d===t.venc)s+=10;return Math.min(s,94)}
function cbCandidatos(e){const b=F2_BANCOS.find(x=>x.id===e.b);const usados=new Set(F2_EXT.filter(x=>x.st==='conc'&&x.id!==e.id).map(x=>x.tit));return F2_TIT.filter(t=>t.u===b.u&&(e.v>0?t.t==='receber':t.t==='pagar')&&!usados.has(t.id)).map(t=>({t,s:cbScore(e,t)})).filter(x=>x.s>=30).sort((a,b)=>b.s-a.s)}
