function cbExtratoTab(){const l=cbLinhas().filter(e=>(!CB_FILTRO||e.st===CB_FILTRO)&&(!CB_Q||semAc(e.desc+' '+e.ident).includes(semAc(CB_Q))));
 return tabela(['Data','Lançamento no banco','Valor','Título casado','Confiança','Situação',''],l.map(e=>{const t=e.tit&&F2_TT(e.tit);const [sl,sc]=CB_ST[e.st];return `<tr class="clk" onclick="cbLinha('${e.id}')" ${tipAttr('Lançamento','Abre o lançamento: títulos candidatos com a confiança, critério usado e histórico.')}>${td('Data',e.d)}${td('Lançamento',`<span class="two"><b>${esc(e.desc)}</b><small class="tl" style="display:block">${e.tipo} · <span class="mono">${esc(e.ident)}</span></small></span>`)}${td('Valor',f2v(e.v))}${td('Título',t?`<span class="two"><span class="mono">${t.id}</span> ${esc(t.q)}<small class="tl" style="display:block">${esc(t.ref)}</small></span>`:'<span class="tl">—</span>')}${td('Confiança',e.conf?f2Conf(e.conf):'—')}${td('Situação',`<span class="badge ${sc}">${sl}${e.dt?' · '+e.dt:''}</span>${e.st==='conc'?`<small class="tl" style="display:block">${e.modo}${e.por?' · '+e.por:''}</small>`:''}`)}${td('',cbAcoes(e))}</tr>`}),'Nada com este filtro')}
function cbAcoes(e){const s='event.stopPropagation();';if(e.st==='sug')return `<span class="row" style="gap:4px;flex-wrap:nowrap"><button class="btn sm" onclick="${s}cbConciliar('${e.id}')">Conciliar</button><button class="btn sm ghost" onclick="${s}cbLinha('${e.id}')">Outro título</button></span>`;
 if(e.st==='div')return `<button class="btn sm warn" onclick="${s}cbDivergencia('${e.id}')">Resolver</button>`;if(e.st==='tar')return `<button class="btn sm sec" onclick="${s}cbTarifa('${e.id}')">Classificar</button>`;return `<button class="btn sm ghost" onclick="${s}cbDesfazer('${e.id}')" ${tipAttr('Desfazer','Volta o lançamento para conciliar. Pede motivo; mês fechado só com o Administrador.')}>Desfazer</button>`}
function cbLinha(id){const e=F2_E(id),b=F2_BANCOS.find(x=>x.id===e.b);const cand=cbCandidatos(e);const [sl,sc]=CB_ST[e.st];
 openDrawer('Extrato · '+e.d+' · '+(e.v<0?'saída':'entrada'),`${kvs([['Lançamento',`<b>${esc(e.desc)}</b>`],['Identificador',`<span class="mono">${esc(e.ident)}</span>`],['Valor',f2v(e.v)],['Conta',b.n+' · '+unidNome(b.u)],['Situação',`<span class="badge ${sc}">${sl}${e.dt?' · '+e.dt:''}</span>`],['Critério',esc(e.crit||'—')]])}
 <h4 style="margin-top:12px">Títulos candidatos ${info('Só aparecem títulos da mesma unidade da conta e do mesmo sentido (entrada casa com a receber; saída com a pagar). A confiança soma: identificador exato 100; valor exato 55; nome parecido 25; mesmo dia 10.')}</h4>
 <div class="at-list">${cand.length?cand.map(({t,s})=>`<div class="at-row"><div class="grow"><b><span class="mono">${t.id}</span> ${esc(t.q)}</b><small>${esc(t.ref)} · vence ${t.venc} · ${fmt(t.v)}${Math.abs(Math.abs(e.v)-t.v)>0.005?` · <b style="color:var(--warn)">diferença ${fmt(Math.abs(e.v)-t.v)}</b>`:''}</small></div>${f2Conf(s)}${e.st!=='conc'?`<button class="btn sm" onclick="cbCasar('${e.id}','${t.id}')">Casar</button>`:e.tit===t.id?'<span class="badge ok">casado</span>':''}</div>`).join(''):'<div class="empty" style="padding:14px"><h4>Nenhum título parecido</h4><p>Use Resolver para lançar como crédito do paciente, devolver ou criar a conta.</p></div>'}</div>
 <div class="alert info" style="margin-top:10px"><span>Conciliar <b>não muda o valor do título</b>. Diferença vira ajuste com motivo (glosa, juros, desconto, taxa), calculado no servidor.</span></div>
 <div class="row" style="margin-top:12px;gap:6px;flex-wrap:wrap">${e.st==='conc'?`<button class="btn sec" onclick="cbDesfazer('${e.id}')">Desfazer conciliação</button>`:e.st==='div'?`<button class="btn warn" onclick="cbDivergencia('${e.id}')">Resolver divergência</button>`:e.st==='tar'?`<button class="btn" onclick="cbTarifa('${e.id}')">Classificar tarifa</button>`:''}<button class="btn ghost" onclick="f2Trilha('Conciliação bancária')">Trilha</button></div>`)}
function cbCasar(id,tid){const e=F2_E(id),t=F2_TT(tid);const dif=Math.round((Math.abs(e.v)-t.v)*100)/100;if(Math.abs(dif)>0.005){closeDrawer();e.tit=tid;e.conf=cbScore(e,t);e.st='div';e.dt=dif<0?'a menor':'a maior';cbDivergencia(id);return}e.tit=tid;e.conf=e.conf||cbScore(e,t);cbOk(e,'manual');closeDrawer()}
function cbConciliar(id){const e=F2_E(id);cbOk(e,'manual')}
function cbOk(e,modo,obs){e.st='conc';e.modo=modo;e.por=FN_USU;f2Aud('Conciliação bancária',`${e.d} ${e.desc} (${fmt(Math.abs(e.v))}) conciliado com ${e.tit||'lançamento novo'}${obs?' · '+obs:''}`);reView();toast(`Conciliado${e.tit?' com '+e.tit:''}: título baixado na data do banco (${e.d}). Registro na trilha.`)}
function cbDesfazer(id){const e=F2_E(id);const fechado=CB_FECH['11/2026'];if(fechado&&!f2Admin()){toast('Novembro está fechado: só o Administrador desfaz, com motivo','warn');return}
 f2Motivo('Desfazer conciliação',`<b>${esc(e.desc)}</b> · ${fmt(Math.abs(e.v))}. O título ${e.tit||''} volta para "em aberto" e o lançamento volta para conciliar. A conciliação antiga fica guardada.`,m=>{e.st=e.conf>=70?'sug':'div';if(!e.dt&&e.st==='div')e.dt='sem título';delete e.por;f2Aud('Conciliação bancária',`Conciliação desfeita: ${e.desc} (${fmt(Math.abs(e.v))}). Motivo: ${m}`);closeDrawer();reView();toast('Conciliação desfeita e registrada na trilha','warn')},'Desfazer','warn')}
function cbDivergencia(id){const e=F2_E(id);const t=e.tit&&F2_TT(e.tit);let corpo='',btn='';
 if(e.dt==='desconto a aprovar'){if(!f2Admin()){toast('Desconto aguardando o Administrador: quem concilia não aprova desconto','warn');return}closeDrawer();cbOk(e,'manual','desconto aprovado pelo Administrador');return}
 if(e.dt==='a menor'||e.dt==='a maior'){const dif=Math.round((Math.abs(e.v)-t.v)*100)/100;corpo=`<p style="font-size:14px">O banco recebeu <b>${fmt(Math.abs(e.v))}</b>; o título <span class="mono">${t.id}</span> (${esc(t.q)}) é de <b>${fmt(t.v)}</b>. Diferença: <b style="color:var(--err)">${fmt(dif)}</b>.</p><div class="field"><label>A diferença é</label><select class="in" id="cbMotDif">${(dif<0?[['glosa','Glosa do convênio (vai para Glosas e recursos)'],['desconto','Desconto concedido (exige aprovação)'],['taxa','Taxa ou tarifa descontada na fonte'],['parcial','Pagamento parcial (o restante continua em aberto)']]:[['juros','Juros e multa por atraso'],['credito','Pagou a mais: crédito do cliente']]).map(([v,x])=>`<option value="${v}">${x}</option>`).join('')}</select></div>${e.dt==='a menor'&&t.orig==='lote TISS'?`<div class="alert warn"><span>O demonstrativo do lote já trouxe as glosas que explicam a diferença. ${info('Glosa: a operadora não pagou um item. Em Glosas e recursos você recorre dentro do prazo.')}</span></div>`:''}`;btn=`<button class="btn" onclick="cbDifOk('${id}')">Conciliar com a diferença</button>`}
 else if(e.dt==='duplicado'){corpo=`<p style="font-size:14px"><b>${esc(e.desc)}</b> pagou ${fmt(e.v)} duas vezes; o título já foi baixado pelo primeiro Pix. Escolha o destino do valor a mais:</p>`;btn=`<button class="btn sec" onclick="cbDestino('${id}','Devolução do Pix (MED) agendada ao pagador')">Devolver o Pix</button><button class="btn" onclick="cbDestino('${id}','Crédito na carteira do paciente')">Crédito do paciente</button>`}
 else{corpo=`<p style="font-size:14px"><b>${esc(e.desc)}</b> · ${fmt(Math.abs(e.v))}. Não há título em aberto que case. ${esc(e.crit||'')}.</p>`;btn=`<button class="btn sec" onclick="cbDestino('${id}','Devolução do Pix (MED) agendada ao pagador')">Devolver</button><button class="btn sec" onclick="cbDestino('${id}','Conta a receber nova criada pelo financeiro')">Criar título</button><button class="btn" onclick="cbDestino('${id}','Crédito na carteira do paciente (usa no reagendamento)')">Crédito do paciente</button>`}
 openModal(`${mh('Resolver divergência · '+e.dt)}<div class="mb">${corpo}<div class="field"><label for="f2Mot">Motivo <span class="req">*</span></label><textarea class="in" id="f2Mot" rows="2" placeholder="Fica na trilha com o seu nome."></textarea><div class="msg" id="f2MotMsg"></div></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button>${btn}</div>`)}
function cbMotLido(){const el=$('#f2Mot');const m=(el.value||'').trim();if(m.length<10){el.closest('.field').classList.add('err');$('#f2MotMsg').textContent='O motivo é obrigatório, com pelo menos 10 letras.';return null}return m}
function cbDifOk(id){const m=cbMotLido();if(!m)return;const e=F2_E(id),t=F2_TT(e.tit);const k=$('#cbMotDif').value;const dif=Math.round((Math.abs(e.v)-t.v)*100)/100;closeModal();closeDrawer();
 if(k==='desconto'&&!f2Admin()){e.st='div';e.dt='desconto a aprovar';f2Aud('Conciliação bancária',`Desconto de ${fmt(Math.abs(dif))} em ${t.id} enviado para aprovação do Administrador. Motivo: ${m}`);reView();toast('Desconto enviado para aprovação do Administrador (quem concilia não aprova desconto)','warn');return}
 const txt={glosa:'glosa de '+fmt(Math.abs(dif))+' lançada em 2.2 Glosas e enviada para Glosas e recursos',desconto:'desconto aprovado',taxa:'taxa lançada em 4.10 Tarifas',parcial:'saldo de '+fmt(Math.abs(dif))+' continua em aberto',juros:'juros de '+fmt(dif)+' lançados como receita',credito:'crédito de '+fmt(dif)+' na carteira do cliente'}[k];
 cbOk(e,'manual',txt+'. Motivo: '+m);if(k==='glosa')retorno('ok','Conciliado com glosa',`Título ${t.id} baixado por ${fmt(Math.abs(e.v))}; ${txt}. Os itens glosados já aparecem com prazo de recurso.`,[{l:'Abrir Glosas e recursos',on:"GL_ABA='glosas';location.hash='glosas'"},{l:'Fechar',sec:true}])}
function cbDestino(id,txt){const m=cbMotLido();if(!m)return;const e=F2_E(id);closeModal();closeDrawer();e.tit=null;cbOk(e,'manual',txt+'. Motivo: '+m)}
function cbTarifa(id){const e=F2_E(id);const acima=Math.abs(e.v)-e.contrato>0.005;
 openModal(`${mh('Classificar tarifa')}<div class="mb">${kvs([['Lançamento',esc(e.desc)],['Cobrado',fmt(Math.abs(e.v))],['Contrato',fmt(e.contrato)+' · '+esc(e.crit)],['Categoria','4.10 · Tarifas bancárias e de cartão'],['Centro de custo',unidNome(F2_BANCOS.find(b=>b.id===e.b).u)]])}${acima?`<div class="alert err" style="margin-top:10px"><span><b>Cobrado acima do contrato:</b> ${fmt(Math.abs(e.v)-e.contrato)} a mais. A IA financeira marcou como anomalia ${info('Compara cada tarifa com o contrato do banco e com a média dos últimos 6 meses.')}.</span></div>`:'<div class="alert ok" style="margin-top:10px"><span>Bate com o contrato do banco.</span></div>'}</div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button>${acima?`<button class="btn sec" onclick="closeModal();cbContestar('${id}')">Contestar com o banco</button>`:''}<button class="btn" onclick="closeModal();cbTarOk('${id}')">Lançar e conciliar</button></div>`)}
function cbTarOk(id){const e=F2_E(id);e.tit=null;cbOk(e,'manual','despesa lançada em 4.10 Tarifas')}
function cbContestar(id){const e=F2_E(id);f2Aud('Conciliação bancária',`Tarifa contestada com o banco: ${e.desc} (${fmt(Math.abs(e.v))}, contrato ${fmt(e.contrato)})`);toast('Contestação registrada; a tarifa fica pendente até o estorno do banco','warn')}
function cbPix(){const l=F2_EXT.filter(e=>(e.tipo==='Pix'||e.tipo==='Boleto')&&F2_BANCOS.find(b=>b.id===e.b).u===cbBanco().u);
 return `<div class="grid g2"><div class="card at-card"><h3>Pix e boletos recebidos ${info('Cada Pix de cobrança tem um identificador (txid) gerado no atendimento; cada boleto, um nosso número. Com eles, a baixa é automática e 100% segura.')}</h3>${tabela(['Data','Pagador','Identificador','Valor','Título'],l.filter(e=>e.v>0).map(e=>`<tr class="clk" onclick="cbLinha('${e.id}')">${td('Data',e.d)}${td('Pagador',esc(e.desc.split('· ')[1]||e.desc))}${td('Identificador',`<span class="mono">${esc(e.ident)}</span>`)}${td('Valor',f2v(e.v))}${td('Título',e.st==='conc'?`<span class="badge ok">${e.tit||'resolvido'}</span>`:`<span class="badge ${CB_ST[e.st][1]}">${CB_ST[e.st][0]}</span>`)}</tr>`))}</div>
 <div class="card at-card"><h3>Cobranças emitidas, aguardando ${info('Pix com QR dinâmico e boletos gerados pela plataforma. Vencido sem pagamento vira aviso para a recepção ou para o faturamento.')}</h3>${tabela(['Emitida','Para','Tipo','Valor','Vence'],[['03/11','Joana Darc Pereira','Pix (link)','R$ 200,00','04/11 09:00'],['03/11','Raimundo Nonato Silva','Pix (link)','R$ 35,00','04/11 09:20'],['01/11','Clínica Vida Plena','Boleto','R$ 11.200,00','10/11'],['31/10','Construtora Mar Azul','Boleto','R$ 3.480,00','<span class="prazo-err">03/11 · vencido</span>']].map(([a,b,c,d,e])=>`<tr>${td('Emitida',a)}${td('Para',b)}${td('Tipo',c)}${td('Valor',d)}${td('Vence',e)}</tr>`))}<p class="tl" style="margin-top:8px">Split ★: Pix e cartão de profissional com split ligado já chegam divididos; só a parte da clínica entra nesta conta (ver Repasse médico).</p></div></div>`}
function cbTarifas(){const l=F2_EXT.filter(e=>e.tipo==='Tarifa');const tot=l.reduce((s,e)=>s+Math.abs(e.v),0);
 return `<div class="card at-card"><h3>Tarifas bancárias e de cartão · novembro ${info('Tarifa conhecida é classificada sozinha em 4.10; a IA compara com o contrato e marca o que vier acima.')}</h3>${tabela(['Data','Conta','Tarifa','Cobrado','Contrato','Situação',''],l.map(e=>{const acima=Math.abs(e.v)-e.contrato>0.005;return `<tr>${td('Data',e.d)}${td('Conta',F2_BANCOS.find(b=>b.id===e.b).n.split(' · ')[0])}${td('Tarifa',esc(e.desc))}${td('Cobrado',fmt(Math.abs(e.v)))}${td('Contrato',fmt(e.contrato))}${td('Situação',e.st==='conc'?'<span class="badge ok">lançada</span>':acima?'<span class="badge err">acima do contrato</span>':'<span class="badge warn">a classificar</span>')}${td('',e.st==='conc'?'':`<button class="btn sm sec" onclick="cbTarifa('${e.id}')">Classificar</button>`)}</tr>`}))}
 <div class="mini" style="margin-top:10px">${miniKpi('Tarifas no mês',fmt(tot),l.length+' lançamentos')}${miniKpi('Taxa de cartão (Cielo)','2,98%','crédito à vista · contrato vigente')}${miniKpi('Acima do contrato',fmt(l.reduce((s,e)=>s+Math.max(0,Math.abs(e.v)-e.contrato),0)),'para contestar','warn')}</div></div>`}
function cbAbertos(){const u=cbBanco().u;const usados=new Set(F2_EXT.filter(e=>e.st==='conc').map(e=>e.tit));const l=F2_TIT.filter(t=>t.u===u&&!usados.has(t.id));
 return `<p class="tl" style="margin-bottom:8px">Títulos de ${unidNome(u)} ainda sem pagamento casado no extrato. Os vencidos viram aviso para quem cobra.</p>${tabela(['Título','Sentido','Quem','Origem','Vence','Valor'],l.map(t=>`<tr>${td('Título',`<span class="mono">${t.id}</span>`)}${td('Sentido',t.t==='receber'?'<span class="badge info">a receber</span>':'<span class="badge neutral">a pagar</span>')}${td('Quem',`<span class="two"><b>${esc(t.q)}</b><small class="tl" style="display:block">${esc(t.ref)}</small></span>`)}${td('Origem',t.orig)}${td('Vence',t.venc)}${td('Valor',fmt(t.v))}</tr>`),'Tudo casado')}<p class="tl" style="margin-top:8px">As contas lançadas à mão ficam em <a href="#financeiro" onclick="FN_ABA='receber'">Financeiro › A receber</a> e <a href="#financeiro" onclick="FN_ABA='pagar'">A pagar</a>.</p>`}
function cbRegras(){return `<div class="card at-card"><h3>Como o casamento automático decide ${info('Regras em ordem. Acima de 95% concilia sozinho; de 70% a 94% vira sugestão para alguém confirmar; abaixo, fica sem par. Cada confirmação manual ensina a próxima.')}</h3>${tabela(['Critério','Confiança','O que acontece'],[['Identificador do Pix (txid) = cobrança gerada no atendimento','100%','concilia sozinho'],['Nosso número do boleto emitido','100%','concilia sozinho'],['Código de barras do boleto pago (anexo da conta)','99%','concilia sozinho'],['Lote da adquirente − taxa contratada = valor creditado','95%','concilia sozinho; a taxa vai para 4.10'],['Valor exato + CNPJ ou nome do pagador + data ±3 dias','85–94%','sugestão'],['Valor exato + data ±3 dias','70–84%','sugestão'],['Valor diferente do título (glosa, desconto, juros)','—','divergência com motivo obrigatório'],['Tarifa conhecida pela descrição','—','classifica em 4.10; acima do contrato vira anomalia']].map(([a,b,c])=>`<tr>${td('Critério',a)}${td('Confiança',b)}${td('O que acontece',c)}</tr>`))}<p class="tl" style="margin-top:8px">O casamento roda no servidor, dentro da unidade da conta. Lançamento repetido do banco (mesmo FITID ou identificador) nunca entra duas vezes.</p></div>`}
function cbSync(){const b=cbBanco();if(b.modo!=='API do Banco Inter'){toast('Esta conta é por OFX: use Importar OFX','warn');return}b.sync='hoje '+hhmm(new Date());f2Aud('Conciliação bancária','Sincronização manual com a API do Banco Inter: nenhum lançamento novo');reView();toast('Banco Inter sincronizado: nenhum lançamento novo desde '+b.sync.replace('hoje ',''))}
function cbOFX(){openModal(`${mh('Importar extrato OFX')}<div class="mb"><div class="field"><label>Conta</label><select class="in">${F2_BANCOS.map(b=>`<option ${b.id===CB_BANCO?'selected':''}>${b.n} · ${unidNome(b.u)}</option>`).join('')}</select></div><div class="empty" style="border:2px dashed var(--border);border-radius:12px;padding:20px"><h4>Arraste o arquivo .ofx aqui</h4><p>ou clique para escolher. O arquivo fica guardado como anexo da importação.</p></div><p class="tl" style="margin-top:8px">Lançamento que já entrou (mesmo FITID) é ignorado. Período fechado não recebe lançamento novo.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();f2Aud('Conciliação bancária','OFX importado: 4 lançamentos lidos, 4 já existiam (ignorados pelo FITID)');toast('OFX lido: 4 lançamentos, todos já importados (nada duplicado)')">Importar</button></div>`)}
function cbFechar(){const p=F2_EXT.filter(e=>e.st!=='conc');if(p.length){listaDrawer('Ainda não dá para fechar novembro',p.map(e=>`<b>${esc(e.desc)}</b><small>${e.d} · ${fmt(Math.abs(e.v))} · ${CB_ST[e.st][0]}${e.dt?' ('+e.dt+')':''} · ${F2_BANCOS.find(b=>b.id===e.b).n.split(' · ')[0]}</small>`),p.length+' lançamento(s) sem conciliar nas duas contas. Resolva todos para fechar.');return}CB_FECH['11/2026']=true;f2Aud('Conciliação bancária','Conciliação de novembro fechada');reView();toast('Novembro fechado: nada muda sem o Administrador')}
GUIDES.conciliacao=['O extrato chega sozinho pela API do Banco Inter (ou importe o OFX dos outros bancos). Pix, boletos e cartão com identificador já entram conciliados.','Confira as sugestões: abra a linha, veja a confiança e o critério, e clique Conciliar ou case com outro título.','Divergência (pagou a menor, em dobro ou sem título) e desfazer pedem motivo; glosa do convênio vai direto para Glosas e recursos.','Classifique as tarifas e conteste as que vierem acima do contrato. No fim do mês, feche a conciliação: depois disso só o Administrador mexe.'];
REGRAS['Conciliação bancária']={aba:'Financeiro · conciliação',itens:[['Fonte','Extrato pela API do banco (Banco Inter, a cada 15 min) ou OFX; lançamento repetido (mesmo FITID/identificador) nunca entra duas vezes.'],['Casamento','No servidor e dentro da unidade da conta: txid do Pix, nosso número e código de barras = automático; valor, CNPJ/nome e data = sugestão com % de confiança; o resto fica sem par.'],['Valor','Conciliar nunca altera o valor do título. Diferença vira ajuste com motivo: glosa (vai para Glosas e recursos), desconto (aprovação do Administrador), taxa, juros ou saldo em aberto.'],['Desfazer','Sempre com motivo; o registro antigo fica guardado. Mês fechado: só o Administrador.'],['Divergências','Pagou a menor, a maior, em dobro ou sem título: cada uma com destino (devolver, crédito do paciente, criar título) e motivo.'],['Tarifas','Classificadas em 4.10 e comparadas com o contrato; acima do contrato vira anomalia para contestar.'],['Fechamento','Mês fechado só com todas as linhas resolvidas; correção posterior vira ajuste no mês aberto.'],['Trilha','Cada conciliação, desfazer e classificação fica na trilha com quem, quando e motivo.']]};

/* =====================================================================================================
   2. REPASSE MÉDICO E DE TERCEIROS: regras, extrato por período, glosa descontada, fechamento com aprovação, split
   ===================================================================================================== */
const F2_IMP=8.65; /* impostos sobre o faturamento (ISS 5% + PIS/COFINS 3,65%, lucro presumido): configuração do estabelecimento */
