function rpSplitSet(id,on){const b=F2_B(id);if(!f2Admin()){toast('Só o Administrador liga ou desliga o split (muda para onde vai o dinheiro)','warn');reView();return}b.split=on;f2Aud('Repasse médico',`Split ${on?'ligado':'desligado'} para ${b.n}`);toast('Split '+(on?'ligado':'desligado')+' para '+b.n+'; vale para os próximos pagamentos')}
