const F2_TABS=['Particular','Unimed','Hapvida','Bradesco'];
const F2_PRECO={'10101012':{Unimed:120,Hapvida:95,Bradesco:140},'40901122':{Unimed:150,Hapvida:120,Bradesco:165},'40901300':{Unimed:110,Hapvida:90,Bradesco:120},'40901467':{Unimed:120,Hapvida:110,Bradesco:130},'40901483':{Unimed:115,Hapvida:95,Bradesco:150},'40901530':{Unimed:140,Hapvida:120,Bradesco:150},'40101010':{Unimed:60,Hapvida:40,Bradesco:65},'20104090':{Unimed:25,Hapvida:18,Bradesco:28},'30101921':{Unimed:280,Hapvida:220,Bradesco:320},'20104138':{Unimed:35,Hapvida:28,Bradesco:40}};
const F2_GLMED={Particular:0,Unimed:2.1,Hapvida:4.8,Bradesco:3.2};
/* Quem recebe repasse em cada procedimento (o profissional principal da agenda) */
const F2_QUEM={'10101012':['p1'],'40901122':['p2'],'40901300':['p2'],'40901467':['p2'],'40901483':['p2'],'40901530':['p2'],'40101010':['t1','te1'],'20104090':[],'30101921':['p3'],'20104138':[]};
/* Centros de custo: custo fixo do mês rateado pelo volume da sala */
const F2_CC=[
 {k:'Ultrassom',n:'Imagem · sala de ultrassom',fixo:14800,vol:410,crit:'aluguel por m² (22 m²), depreciação do GE Logiq P9, contrato de manutenção, recepcionista dedicada'},
 {k:'Consultório',n:'Consultórios 1 e 2',fixo:11800,vol:620,crit:'aluguel por m² (2 × 14 m²), limpeza, secretária, prontuário e telemedicina'},
 {k:'Procedimentos',n:'Sala de procedimentos',fixo:3600,vol:260,crit:'aluguel por m² (12 m²), enfermagem (rateio de horas), eletrocardiógrafo'}];
let CM_TAB='Particular',CM_ORD='margem';
function cmCalc(c,tab,preco,vol){const p=PROC(c);const conv=tab;const pr=preco!=null?preco:(tab==='Particular'?p.preco:(F2_PRECO[c]||{})[tab]||0);const ins=typeof stkKitCusto==='function'?stkKitCusto(c):0;const gl=pr*(F2_GLMED[tab]||0)/100;
 const rep=(F2_QUEM[c]||[]).reduce((s,b)=>s+rpValor(rpRegra(b,c,conv==='Particular'?'Particular':conv),pr,gl),0);const imp=pr*F2_IMP/100;const cc=F2_CC.find(x=>x.k===p.sala)||F2_CC[1];const rat=cc.fixo/(vol||cc.vol);
 const custo=ins+rep+imp+rat+gl;const mg=pr-custo;return {p,tab,pr,ins,rep,imp,rat,gl,cc,custo,mg,pct:pr?mg/pr*100:0,sem:!(pr>0)}}
function cmLista(k){const l=[];PROCEDIMENTOS.filter(p=>p.preco>0).forEach(p=>F2_TABS.forEach(t=>{const x=cmCalc(p.c,t);if(!x.sem&&(k==='prej'?x.mg<0:x.mg>=0&&x.pct<20))l.push(x)}));openDrawer(k==='prej'?'Em prejuízo':'Margem baixa (abaixo de 20%)',`<div class="at-list">${l.map(x=>`<div class="at-row clk" onclick="cmDetalhe('${x.p.c}','${x.tab}')"><div class="grow"><b>${x.p.n} · ${x.tab}</b><small>preço ${fmt(x.pr)} · custo real ${fmt(x.custo)} · lucro ${fmt(x.mg)}</small></div>${cmTag(x)}</div>`).join('')||'<div class="empty"><h4>Nenhum</h4></div>'}</div>`)}
const cmTag=x=>x.sem?`<span class="badge neutral" ${tipAttr('Sem preço','Esta tabela não tem preço para o procedimento. Cadastre em Tabelas de preço ou deixe sem atender por este convênio.')}>sem preço</span>`:x.mg<0?`<span class="badge err pisca" ${tipAttr('Prejuízo','O custo real passa do preço desta tabela. Clique para ver a composição e simular.')}>PREJUÍZO</span>`:x.pct<20?`<span class="mg baixa" ${tipAttr('Margem baixa','Abaixo de 20% sobre o preço (mesma regra das tabelas de preço do laboratório).')}>MARGEM BAIXA ${Math.round(x.pct)}%</span>`:`<span class="mg ok">${Math.round(x.pct)}%</span>`;
VIEWS['custos-procedimento']=()=>{const procs=PROCEDIMENTOS.filter(p=>p.preco>0);const todos=[];procs.forEach(p=>F2_TABS.forEach(t=>{const x=cmCalc(p.c,t);if(!x.sem)todos.push(x)}));const l=procs.map(p=>cmCalc(p.c,CM_TAB)).sort((a,b)=>CM_ORD==='margem'?a.pct-b.pct:b.mg-a.mg);
 const prej=todos.filter(x=>x.mg<0),baixa=todos.filter(x=>x.mg>=0&&x.pct<20);
 return `${pageHead('Financeiro','Custo e margem por procedimento','Custo real de cada procedimento por tabela: preço − insumos do estoque (kit) − repasse − impostos − rateio do custo fixo da sala − glosa média do convênio. Dados de exemplo.',`${rulesBtn('Custo e margem')}${f2TrilhaBtn('Custo e margem')}<a class="btn sec" href="#precos" ${tipAttr('Tabelas de preço','Corrige o preço por tabela; cada mudança vira versão nova.')}>Tabelas de preço</a><button class="btn" onclick="cmSimular()">Simular preço</button>`)}
 <div class="mini">${miniKpi('Procedimentos × tabelas',todos.length,procs.length+' procedimentos · '+F2_TABS.length+' tabelas')}${miniKpi('Em prejuízo',prej.length,'custo maior que o preço','err',"cmLista('prej')")}${miniKpi('Margem baixa',baixa.length,'abaixo de 20%','warn',"cmLista('baixa')")}${miniKpi('Impostos','8,65%','ISS 5% + PIS/COFINS 3,65%')}${miniKpi('Custo fixo rateado',fmt(F2_CC.reduce((s,c)=>s+c.fixo,0)),'3 centros de custo · outubro')}</div>
 <div class="row" style="gap:6px;flex-wrap:wrap;margin:12px 0"><span class="tl">Tabela:</span>${F2_TABS.map(t=>chip(t,CM_TAB===t,`CM_TAB='${t}';reView()`)).join('')}<span class="tl" style="margin-left:auto">Ordenar:</span>${chip('Pior margem primeiro',CM_ORD==='margem',"CM_ORD='margem';reView()")}${chip('Maior lucro por unidade',CM_ORD==='lucro',"CM_ORD='lucro';reView()")}</div>
 <div class="card at-card"><h3>${CM_TAB} · custo real por procedimento ${info('Insumos: kit do procedimento no estoque, pelo custo médio. Repasse: regra vigente do profissional. Rateio: custo fixo do centro de custo ÷ volume do mês. Glosa: média dos últimos 12 meses do convênio. Clique na linha para ver a conta.')}</h3>
 ${tabela(['Procedimento','Preço','Insumos','Repasse','Impostos','Rateio','Glosa média','Lucro','Margem'],l.map(x=>`<tr class="clk ${x.mg<0?'prejuizo':''}" onclick="cmDetalhe('${x.p.c}','${CM_TAB}')">${td('Procedimento',`<span class="two"><b>${x.p.n}</b><small class="tl" style="display:block">TUSS ${x.p.c} · ${x.p.tipo}</small></span>`)}${td('Preço',fmt(x.pr))}${td('Insumos',fmt(x.ins))}${td('Repasse',fmt(x.rep))}${td('Impostos',fmt(x.imp))}${td('Rateio',fmt(x.rat))}${td('Glosa média',x.gl?fmt(x.gl):'—')}${td('Lucro',x.sem?'—':`<b class="${x.mg<0?'f2-menos':''}">${fmt(x.mg)}</b>`)}${td('Margem',cmTag(x))}</tr>`))}</div>
 <div class="grid g2" style="margin-top:12px"><div class="card at-card"><h3>Ranking de margem · todas as tabelas ${info('Os dez piores pares procedimento × tabela. É aqui que a negociação com o convênio ou a revisão do repasse rende mais.')}</h3><div class="barras">${todos.sort((a,b)=>a.pct-b.pct).slice(0,10).map(x=>`<div class="clk" onclick="cmDetalhe('${x.p.c}','${x.tab}')"><span>${x.p.n.replace('Consulta em consultório','Consulta')} · ${x.tab}</span><span class="b"><i style="width:${Math.max(2,Math.min(100,Math.round(Math.max(0,x.pct)*1.6)))}%;background:${x.mg<0?'var(--err)':x.pct<20?'var(--warn)':'var(--ok)'}"></i></span><b>${Math.round(x.pct)}%</b></div>`).join('')}</div></div>
 <div class="card at-card"><h3>Centros de custo e rateio ${info('O custo fixo do mês (aluguel, pessoal, depreciação, manutenção) vem da DRE por centro de custo e é dividido pelo volume de atendimentos da sala.')}</h3>${tabela(['Centro de custo','Custo fixo/mês','Volume','Por atendimento'],F2_CC.map(c=>`<tr title="${esc(c.crit)}">${td('Centro',`<span class="two"><b>${c.n}</b><small class="tl" style="display:block">${c.crit}</small></span>`)}${td('Custo fixo',fmt(c.fixo))}${td('Volume',c.vol)}${td('Por atendimento',fmt(c.fixo/c.vol))}</tr>`))}<p class="tl" style="margin-top:8px">Laboratório: a margem por exame está em <a href="#precos">Tabelas de preço</a> (custo do exame + tabela de cada posto). O resultado consolidado fica na <a href="#financeiro" onclick="FN_ABA='dre'">DRE</a>.</p></div></div>
 ${piada(83,{financeiro:'Margem real é a margem depois que o gel, o repasse, o imposto, o aluguel e a glosa passaram o pente fino.',admin:'Descobrir que a consulta Unimed dá prejuízo é como descobrir que o cafezinho da recepção é o item mais caro do mês.',todos:'Ultrassom sem gel não dá. Margem sem conta também não.'})}`};
function cmDetalhe(c,tab){tab=tab||CM_TAB;const x=cmCalc(c,tab);const kit=typeof stkKitItens==='function'?stkKitItens(c):[];const quem=(F2_QUEM[c]||[]).map(b=>{const r=rpRegra(b,c,tab);return `${F2_B(b).n}: ${rpRegraTxt(r)}`});
 openDrawer(x.p.n+' · '+tab,`<div class="f2-cascata"><div><span>Preço na tabela ${tab}</span><b>${fmt(x.pr)}</b></div><div><span>− Insumos (kit do estoque)<small>${kit.length?kit.map(k=>`${f2n(k.q)} ${k.un.toLowerCase()} ${esc(k.n.toLowerCase())}`).join(' · '):'sem kit cadastrado'}</small></span><b>${fmt(x.ins)}</b></div><div><span>− Repasse<small>${quem.join(' · ')||'equipe assalariada (no rateio)'}</small></span><b>${fmt(x.rep)}</b></div><div><span>− Impostos<small>${String(F2_IMP).replace('.',',')}% sobre o preço</small></span><b>${fmt(x.imp)}</b></div><div><span>− Rateio do custo fixo<small>${x.cc.n}: ${fmt(x.cc.fixo)} ÷ ${x.cc.vol} atendimentos</small></span><b>${fmt(x.rat)}</b></div><div><span>− Glosa média<small>${tab}: ${String(F2_GLMED[tab]||0).replace('.',',')}% nos últimos 12 meses</small></span><b>${fmt(x.gl)}</b></div><div class="tot"><span>Lucro por atendimento</span><span>${fmt(x.mg)} · ${cmTag(x)}</span></div></div>
 <h4 style="margin-top:12px">Nas outras tabelas</h4><div class="at-list">${F2_TABS.map(t=>{const y=cmCalc(c,t);return `<div class="at-row clk" onclick="cmDetalhe('${c}','${t}')"><div class="grow"><b>${t}</b><small>preço ${fmt(y.pr)} · lucro ${fmt(y.mg)}</small></div>${cmTag(y)}</div>`}).join('')}</div>
 <div class="row" style="margin-top:12px;gap:6px;flex-wrap:wrap"><button class="btn" onclick="cmSimular('${c}','${tab}')">Simular preço</button><a class="btn sec" href="#estoque-itens">Kit no estoque</a><a class="btn ghost" href="#repasse" onclick="RP_ABA='regras'">Regras de repasse</a></div>`)}
function cmSimular(c,tab){c=c||PROCEDIMENTOS.find(p=>p.preco>0).c;tab=tab||CM_TAB;const x=cmCalc(c,tab);
 openModal(`${mh('Simulador de preço')}<div class="mb"><div class="f2-sim"><div class="field"><label>Procedimento</label><select class="in" id="smP" onchange="cmSimCalc(true)">${PROCEDIMENTOS.filter(p=>p.preco>0).map(p=>`<option value="${p.c}" ${p.c===c?'selected':''}>${p.n}</option>`).join('')}</select></div><div class="field"><label>Tabela</label><select class="in" id="smT" onchange="cmSimCalc(true)">${F2_TABS.map(t=>`<option ${t===tab?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Preço simulado (R$)</label><input class="in" id="smV" inputmode="decimal" value="${String(x.pr).replace('.',',')}" oninput="cmSimCalc()"></div><div class="field"><label>Volume do mês na sala</label><input class="in" id="smQ" inputmode="numeric" value="${x.cc.vol}" oninput="cmSimCalc()"></div></div><div id="smOut" style="margin-top:10px"></div><p class="tl" style="margin-top:8px">Simulação não muda nada. Para mudar o preço, use Tabelas de preço (versão nova com vigência) ou negocie com o convênio.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><a class="btn" href="#precos" onclick="closeModal()">Ir para Tabelas de preço</a></div>`);cmSimCalc()}
function cmSimCalc(reset){const c=$('#smP').value,t=$('#smT').value;if(reset){const b=cmCalc(c,t);$('#smV').value=String(b.pr).replace('.',',');$('#smQ').value=b.cc.vol}const pr=parseFloat(($('#smV').value||'0').replace(',','.'))||0,vol=parseInt($('#smQ').value,10)||1;const x=cmCalc(c,t,pr,vol);
 /* Preço mínimo para 20%: as parcelas proporcionais (impostos, glosa, repasse percentual) e as fixas (insumos, rateio, repasse fixo) */
 const a=cmCalc(c,t,100,vol),b=cmCalc(c,t,200,vol);const prop=(b.custo-a.custo)/100;const fixo=a.custo-prop*100;const min20=prop<0.8?fixo/(0.8-prop):0;const eq=prop<1?fixo/(1-prop):0;
 $('#smOut').innerHTML=`<div class="mini">${miniKpi('Lucro por atendimento',fmt(x.mg),'custo real '+fmt(x.custo),x.mg<0?'err':x.pct<20?'warn':'ok')}${miniKpi('Margem',Math.round(x.pct)+'%',x.mg<0?'prejuízo':x.pct<20?'abaixo de 20%':'ok',x.mg<0?'err':x.pct<20?'warn':'ok')}${prop>=0.75?miniKpi('Preço mínimo p/ 20%','inviável',`repasse %, impostos e glosa já levam ${Math.round(prop*100)}% do preço: revise a regra de repasse`,'err'):miniKpi('Preço mínimo p/ 20%',fmt(Math.ceil(min20*100)/100),'nesta tabela e volume')}${miniKpi('Empate (lucro zero)',prop<1?fmt(Math.ceil(eq*100)/100):'inviável','')}</div><p class="tl" style="margin-top:6px">Rateio com ${vol} atendimentos: ${fmt(x.rat)} por atendimento · repasse ${fmt(x.rep)} · insumos ${fmt(x.ins)} · impostos ${fmt(x.imp)} · glosa ${fmt(x.gl)}.</p>`}
