function glAgrupa(k){const m={};F2_GL.forEach(g=>{const x=k==='mot'?g.cod+' · '+g.mot:k==='conv'?glLote(g.l).c:g.area;m[x]=(m[x]||0)+g.v});return Object.entries(m).sort((a,b)=>b[1]-a[1])}
function glPainel(){const bl=(t,k,tip)=>{const a=glAgrupa(k),mx=a[0][1];return `<div class="card at-card"><h3>${t} ${info(tip)}</h3><div class="barras">${a.map(([n,v])=>barra(esc(n),v,mx,fmt(v))).join('')}</div></div>`};
 return `<div class="grid g2">${bl('Por motivo','mot','Código da tabela de mensagens TISS e descrição. O motivo mais caro é o primeiro a atacar.')}${bl('Por área que causou','area','Para corrigir na origem: recepção (autorização, carteirinha), médico (CID, justificativa, assinatura), faturamento (código, valor, duplicidade).')}${bl('Por convênio','conv','Valor glosado por operadora nos lotes com demonstrativo.')}
 <div class="card at-card"><h3>Glosa no repasse ${info('O repasse desconta a glosa na proporção do glosado; se o recurso reverter, devolve no próximo fechamento.')}</h3><div class="at-list">${F2_GL.filter(g=>g.prof).map(g=>`<div class="at-row"><div class="grow"><b>${F2_B(g.prof).n}</b><small>${g.item} · ${g.pac} · ${g.st}</small></div><b class="${g.st==='Revertida'?'':'f2-menos'}">${g.st==='Revertida'?'devolvido':'− repasse'}</b></div>`).join('')}</div><a class="btn sm ghost" href="#repasse" style="margin-top:8px">Abrir repasse</a></div></div>`}
function glLotes(){return `${tabela(['Lote','Convênio','Competência','Guias','Enviado','Pago','Glosado','% glosa','TISS','Situação',''],F2_LOTES.map(l=>{const gl=l.pago!=null?Math.round((l.env-l.pago)*100)/100:null;return `<tr class="clk" onclick="glLoteDet('${l.l}')">${td('Lote',`<span class="mono">${l.l}</span>`)}${td('Convênio',l.c)}${td('Competência',l.comp)}${td('Guias',l.guias)}${td('Enviado',fmt(l.env))}${td('Pago',l.pago!=null?fmt(l.pago):'—')}${td('Glosado',gl!=null?`<span class="f2-menos">${fmt(gl)}</span>`:'—')}${td('% glosa',gl!=null?f2pct(gl/l.env*100):'—')}${td('TISS',l.ver)}${td('Situação',`<span class="badge ${l.st==='Em recurso'?'acc':l.st==='Demonstrativo recebido'?'warn':l.st==='Enviado'?'info':'neutral'}">${l.st}</span>`)}${td('',l.st==='Enviado'?`<button class="btn sm sec" onclick="event.stopPropagation();glImportar('${l.l}')">Importar demonstrativo</button>`:l.st==='Em montagem'?`<button class="btn sm sec" onclick="event.stopPropagation();GL_ABA='ia';reView()">Ver riscos (IA)</button>`:'')}</tr>`}))}<p class="tl" style="margin-top:8px">Lotes a partir de novembro/2026 saem em TISS 4.02.00; cada lote guarda a versão em que foi enviado. O pagamento do lote é casado na <a href="#conciliacao">Conciliação bancária</a>.</p>`}
function glLoteDet(id){const l=glLote(id);const gs=F2_GL.filter(g=>g.l===id);const gl=l.pago!=null?l.env-l.pago:0;
 openDrawer('Lote '+l.l,`${kvs([['Convênio',l.c],['Competência',l.comp],['Guias',l.guias],['Enviado',fmt(l.env)],['Pago',l.pago!=null?fmt(l.pago):'aguardando'],['Glosado',l.pago!=null?fmt(gl)+' ('+f2pct(gl/l.env*100)+')':'—'],['Protocolo',l.prot||'—'],['Demonstrativo',l.dem?'recebido em '+l.dem:'—'],['Prazo de recurso',l.prazo+' dias do demonstrativo'],['Versão TISS',l.ver]])}
 ${gs.length?`<h4 style="margin-top:10px">Glosas do lote</h4><div class="at-list">${gs.map(g=>`<div class="at-row clk" onclick="glItem('${g.id}')"><div class="grow"><b>${g.g} · ${g.item}</b><small>${g.cod} · ${g.mot} · ${g.pac}</small></div><b>${fmt(g.v)}</b><span class="badge ${GL_ST[g.st]}">${g.st}</span></div>`).join('')}</div><p class="tl" style="margin-top:6px">Soma das glosas: ${fmt(gs.reduce((s,g)=>s+g.v,0))} ${Math.abs(gs.reduce((s,g)=>s+g.v,0)-gl)<0.01?'= diferença do pagamento ✓':''}</p>`:''}
 <div class="row" style="margin-top:12px;gap:6px"><button class="btn sec" onclick="toast('XML do lote ${l.l} (TISS ${l.ver}) baixado')">Baixar XML</button>${l.st==='Enviado'?`<button class="btn" onclick="glImportar('${l.l}')">Importar demonstrativo</button>`:''}</div>`)}
function glImportar(l){openModal(`${mh('Importar demonstrativo de retorno')}<div class="mb"><div class="field"><label>Lote</label><select class="in" id="glImpL">${F2_LOTES.filter(x=>x.prot).map(x=>`<option ${x.l===l?'selected':''}>${x.l}</option>`).join('')}</select></div><div class="empty" style="border:2px dashed var(--border);border-radius:12px;padding:18px"><h4>Arraste o XML do demonstrativo (análise da conta)</h4><p>ou busque pelo webservice da operadora.</p></div><p class="tl" style="margin-top:8px">O sistema casa guia a guia e item a item; cada diferença vira glosa com código, motivo e prazo de recurso. Nada é digitado à mão.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="glImpOk()">Importar</button></div>`)}
function glImpOk(){const l=glLote($('#glImpL').value);closeModal();if(l.st!=='Enviado'){toast('Demonstrativo de '+l.l+' já importado; nada duplicado','warn');return}l.st='Demonstrativo recebido';l.dem='04/11';l.pago=19820-64.80;F2_GL.unshift({id:'G'+(F2_GL.length+1),l:l.l,g:'SADT 0861',pac:'Luana Ferreira Castro',item:'US abdome total',cod:'1406',mot:'Falta de justificativa clínica (CID)',v:64.80,prazo:'19/11',st:'Nova',area:'Médico',prof:'p2'});f2Aud('Glosas e recursos',`Demonstrativo de ${l.l} importado: 1 glosa (R$ 64,80)`);GL_ABA='lotes';reView();toast('Demonstrativo casado guia a guia: 72 guias, 1 glosa de R$ 64,80 com prazo até 19/11')}
function glItens(){const l=F2_GL.filter(g=>!GL_CONV||glLote(g.l).c===GL_CONV);return `<div class="filters">${['',...new Set(F2_LOTES.map(l=>l.c))].map(c=>chip(c||'Todos os convênios',GL_CONV===c,`GL_CONV='${c}';reView()`)).join('')}</div>${tabela(['Guia','Paciente','Item','Motivo','Valor','Prazo','Área','Situação',''],l.map(g=>`<tr class="clk" onclick="glItem('${g.id}')">${td('Guia',`<span class="two"><span class="mono">${g.g}</span><small class="tl" style="display:block">${g.l}</small></span>`)}${td('Paciente',esc(g.pac))}${td('Item',g.item)}${td('Motivo',`<span class="two"><b class="mono">${g.cod}</b> ${g.mot}</span>`)}${td('Valor',fmt(g.v))}${td('Prazo',glPrazo(g))}${td('Área',g.area)}${td('Situação',`<span class="badge ${GL_ST[g.st]}">${g.st}</span>`)}${td('',g.st==='Nova'?`<span class="row" style="gap:4px;flex-wrap:nowrap"><button class="btn sm" onclick="event.stopPropagation();glRecorrer('${g.id}')">Recorrer</button><button class="btn sm ghost" onclick="event.stopPropagation();glPerda('${g.id}')">Aceitar perda</button></span>`:g.st==='Perda a aprovar'?`<button class="btn sm sec" onclick="event.stopPropagation();glAprovarPerda('${g.id}')">Aprovar perda</button>`:'')}</tr>`))}`}
function glItem(id){const g=F2_G(id),l=glLote(g.l);openDrawer('Glosa · '+g.g,`${kvs([['Convênio',l.c+' · lote '+l.l],['Paciente',esc(g.pac)],['Item',g.item],['Motivo',`<b class="mono">${g.cod}</b> · ${g.mot}`],['Valor glosado',fmt(g.v)],['Prazo do recurso',glPrazo(g)],['Área que causou',g.area],['Repasse',g.prof?`${F2_B(g.prof).n}: descontado na proporção do glosado`:'sem repasse'],['Situação',`<span class="badge ${GL_ST[g.st]}">${g.st}</span>${g.rec?' · '+g.rec:''}${g.aprov?' · aprovada por '+g.aprov:''}`]])}
 <h4 style="margin-top:10px">Documentos da guia</h4><div class="at-list">${['Guia SP/SADT assinada.pdf','Pedido médico.jpg',g.cod==='1803'?null:'Autorização A7F2-9910.pdf',g.rec?'Recurso '+g.rec+' (XML TISS).xml':null].filter(Boolean).map(a=>`<div class="at-row clk" onclick="toast('${a} aberto')"><div class="grow">${a}<small>anexo da guia</small></div></div>`).join('')}</div>
 <div class="row" style="margin-top:12px;gap:6px;flex-wrap:wrap">${g.st==='Nova'?`<button class="btn" onclick="glRecorrer('${g.id}')">Recorrer</button><button class="btn ghost" onclick="glPerda('${g.id}')">Aceitar perda</button>`:''}${g.st==='Em recurso'?`<button class="btn sec" onclick="glResposta('${g.id}')">Registrar resposta</button>`:''}</div>`)}
function glRecorrer(id){const g=F2_G(id);openModal(`${mh('Recurso de glosa · '+g.g)}<div class="mb">${kvs([['Item',g.item+' · '+fmt(g.v)],['Motivo da operadora',g.cod+' · '+g.mot],['Prazo',g.prazo]])}<div class="field" style="margin-top:10px"><label for="glJus">Justificativa <span class="req">*</span></label><textarea class="in" id="glJus" rows="3">${g.cod==='1803'?'Procedimento autorizado por telefone em 12/09, senha 554120 (protocolo da operadora anexado).':g.cod==='1201'?'Código corrigido para o TUSS vigente 40304361; reapresentação do item com o código correto.':g.cod==='1909'?'':'Indicação clínica e CID informados pelo médico solicitante (relatório anexo).'}</textarea><div class="msg" id="glJusMsg"></div></div><div class="field"><label>Anexos</label><div class="row" style="gap:6px;flex-wrap:wrap">${['Pedido médico','Autorização/senha','Relatório médico','Guia assinada'].map(a=>chip(a,true,"this.classList.toggle('on')")).join('')}</div></div><p class="tl">Gera a guia de recurso de glosa em TISS 4.02.00, assinada, para o portal ou webservice da operadora. Resposta esperada em até 30 dias.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="glRecOk('${id}')">Enviar recurso</button></div>`)}
function glRecOk(id){const j=($('#glJus').value||'').trim();if(j.length<15){$('#glJus').closest('.field').classList.add('err');$('#glJusMsg').textContent='Escreva a justificativa (pelo menos 15 letras).';return}const g=F2_G(id);g.st='Em recurso';g.rec='REC-0'+(GL_SEQ++);closeModal();closeDrawer();f2Aud('Glosas e recursos',`Recurso ${g.rec} enviado: ${g.g} (${g.item}, ${fmt(g.v)}). Justificativa: ${j}`);reView();toast(`Recurso ${g.rec} enviado (TISS 4.02.00); resposta esperada até 04/12`)}
function glPerda(id){const g=F2_G(id);f2Motivo('Aceitar perda · '+g.g,`${g.item} · ${fmt(g.v)} (${g.cod} · ${g.mot}). A glosa vira dedução em 2.2 e não volta. ${g.v>100?'<b>Acima de R$ 100,00: vai para aprovação do Administrador</b> (quem aceita não aprova).':''}`,m=>{if(g.v>100&&!f2Admin()){g.st='Perda a aprovar';f2Aud('Glosas e recursos',`Perda de ${g.g} (${fmt(g.v)}) enviada para aprovação. Motivo: ${m}`);closeDrawer();reView();toast('Perda enviada para aprovação do Administrador','warn');return}g.st='Perda aceita';g.aprov=FN_USU;f2Aud('Glosas e recursos',`Perda aceita em ${g.g} (${fmt(g.v)}). Motivo: ${m}`);closeDrawer();reView();toast('Perda aceita e lançada em 2.2 Glosas de convênio')},'Aceitar perda','warn')}
function glAprovarPerda(id){const g=F2_G(id);if(!f2Admin()){toast('Só o Administrador aprova perda acima de R$ 100,00','warn');return}g.st='Perda aceita';g.aprov=FN_USU;f2Aud('Glosas e recursos',`Perda de ${g.g} (${fmt(g.v)}) aprovada`);reView();toast('Perda aprovada e lançada em 2.2')}
function glResposta(id){const g=F2_G(id);openModal(`${mh('Resposta do recurso '+(g.rec||''))}<div class="mb"><p style="font-size:14px">${g.g} · ${g.item} · ${fmt(g.v)}</p><p class="tl">Revertida: o valor vira conta a receber do convênio e o repasse devolve o desconto no próximo fechamento. Mantida: vira perda (com motivo).</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn sec" onclick="closeModal();glPerda('${id}')">Mantida pela operadora</button><button class="btn" onclick="glRevertida('${id}')">Revertida</button></div>`)}
function glRevertida(id){const g=F2_G(id);g.st='Revertida';closeModal();closeDrawer();if(g.prof){const p=F2_PROD.find(x=>x.b===g.prof&&x.gl&&x.pac===g.pac);if(p){p.gl=0;p.st='liberado'}}f2Aud('Glosas e recursos',`Recurso ${g.rec} revertido: ${fmt(g.v)} volta a receber do convênio`);reView();toast(`${fmt(g.v)} recuperado: conta a receber criada${g.prof?' e repasse liberado para o próximo fechamento':''}`)}
function glRecursos(){const l=F2_GL.filter(g=>g.rec);return `${tabela(['Recurso','Guia','Item','Valor','Enviado','Resposta até','Situação',''],l.map(g=>`<tr class="clk" onclick="glItem('${g.id}')">${td('Recurso',`<span class="mono">${g.rec}</span>`)}${td('Guia',g.g+' · '+glLote(g.l).c)}${td('Item',g.item)}${td('Valor',fmt(g.v))}${td('Enviado',g.rec==='REC-0398'?'01/10':g.rec==='REC-0409'?'24/10':g.rec==='REC-0412'?'30/10':'04/11')}${td('Resposta até',g.rec==='REC-0398'?'31/10':g.rec==='REC-0409'?'23/11':g.rec==='REC-0412'?'29/11':'04/12')}${td('Situação',`<span class="badge ${GL_ST[g.st]}">${g.st}</span>`)}${td('',g.st==='Em recurso'?`<button class="btn sm sec" onclick="event.stopPropagation();glResposta('${g.id}')">Registrar resposta</button>`:'')}</tr>`),'Nenhum recurso')}<p class="tl" style="margin-top:8px">Taxa de reversão nos últimos 12 meses: 58% (Unimed 64%, Hapvida 49%, Bradesco 61%).</p>`}
function glIA(){return `<div class="alert info"><span><b>IA anti-glosa por convênio ★</b> aprendeu com 1.284 glosas de nov/2025 a out/2026 e revisa cada guia antes de o lote fechar, somando aos seis pontos de risco do pré-faturamento. Em setembro, acertou 87% das glosas que previu. ${info('O modelo roda no servidor, por convênio; aqui só aparece o resultado. Quem decide é o faturista: corrigir, reter ou enviar assim mesmo com motivo.')}</span></div>
 <div class="stack" style="display:flex;flex-direction:column;gap:8px;margin-top:10px">${F2_IA.sort((a,b)=>b.risco-a.risco).map((x,i)=>`<div class="f2-ia"><div class="sc ${x.risco>=60?'alto':x.risco>=35?'medio':'baixo'}">${x.risco}%</div><div class="bd"><b>${x.g} · ${esc(x.pac)} · ${x.conv}</b><small>${PROC(x.proc).n} · ${fmt(x.v)}</small>${x.mot.map(m=>`<small>• ${esc(m)}</small>`).join('')}<small><b>Sugestão:</b> ${esc(x.acao)}</small></div><div class="row" style="gap:4px;flex-direction:column;align-items:stretch">${x.risco>=35?`<button class="btn sm" onclick="glIAFix(${i},'corrigida')">Corrigir</button><button class="btn sm ghost" onclick="glIAFix(${i},'retida')">Reter</button><button class="btn sm ghost" onclick="glIAEnviar(${i})">Enviar assim</button>`:'<span class="badge ok">liberada</span>'}</div></div>`).join('')}</div>
 <div class="card at-card" style="margin-top:12px"><h3>O que a IA aprendeu por convênio</h3>${tabela(['Convênio','Padrão','Glosas que explicou','Ação na origem'],[['Hapvida','US transvaginal e obstétrica sem CID ou sem senha','42 de 135','CID obrigatório na solicitação de US para Hapvida'],['Unimed','Valor acima da tabela depois do reajuste de 01/10','19','Tabela vigente puxada na hora da guia'],['Bradesco','Consulta sem autorização em plano com exigência','11','Aviso na recepção ao marcar'],['Camed','Campos novos da TISS 4.02 vazios','novo (lote de novembro)','Preenchimento padrão na guia']].map(r=>`<tr>${r.map((v,j)=>td(['Convênio','Padrão','Glosas','Ação'][j],v)).join('')}</tr>`))}</div>`}
function glIAFix(i,acao){const x=F2_IA[i];x.risco=acao==='corrigida'?9:x.risco;f2Aud('Glosas e recursos',`IA anti-glosa: guia ${x.g} ${acao} (${x.acao})`);if(acao==='retida')F2_IA.splice(i,1);reView();toast(acao==='corrigida'?`Guia ${x.g} corrigida: risco caiu para 9%`:`Guia ${x.g} retida fora do lote; volta quando a pendência for resolvida`,acao==='retida'?'warn':'ok')}
function glIAEnviar(i){const x=F2_IA[i];f2Motivo('Enviar guia com risco · '+x.g,`Risco de ${x.risco}% de glosa (${esc(x.mot[0])}). Se for glosada, o motivo escrito aqui aparece no recurso.`,m=>{x.risco=0;f2Aud('Glosas e recursos',`Guia ${x.g} enviada com risco apontado pela IA. Motivo: ${m}`);F2_IA.splice(i,1);reView();toast('Guia segue no lote com o motivo registrado','warn')},'Enviar assim mesmo','warn')}
GUIDES.glosas=['Importe o demonstrativo de retorno do lote: o sistema casa guia a guia e cria cada glosa com código, motivo e prazo de recurso.','Em Glosas por item, recorra antes do prazo (justificativa e anexos geram a guia de recurso TISS 4.02) ou aceite a perda com motivo; acima de R$ 100,00 o Administrador aprova.','Registre a resposta da operadora: revertida volta a receber e devolve o repasse; mantida vira perda.','Antes de fechar o próximo lote, revise a IA anti-glosa: corrija, retenha ou envie com motivo as guias de risco alto.'];
REGRAS['Glosas e recursos']={aba:'Faturamento TISS · glosas',itens:[['Lote','Por convênio e competência; guarda a versão TISS (4.02.00 a partir de nov/2026) e o protocolo.'],['Demonstrativo','Importado (XML ou webservice) e casado guia a guia e item a item; cada diferença vira glosa com código da tabela de mensagens TISS. Ninguém digita glosa.'],['Prazo','Prazo de recurso por convênio, contado do demonstrativo; aviso em 7 e em 2 dias.'],['Recurso','Justificativa e anexos obrigatórios; gera a guia de recurso em TISS 4.02; resposta registrada: revertida (vira a receber) ou mantida (perda).'],['Perda','Sempre com motivo; acima de R$ 100,00, aprovação do Administrador (quem aceita não aprova). Lançada em 2.2.'],['Repasse','Glosa desconta do repasse na proporção do glosado; revertida devolve no próximo fechamento.'],['Pagamento','O pagamento do lote é conciliado no banco; a diferença do pagamento tem de bater com a soma das glosas.'],['IA anti-glosa ★','Por convênio, aprende com as glosas passadas e pontua cada guia antes do envio; corrigir, reter ou enviar com motivo.'],['Área','Cada glosa marca a área que causou (recepção, médico, faturamento) para corrigir na origem.']]};
